# region: digest
def digest(raw):
    out = []
    for tok in raw:
        s = tok.strip()
        if s.isdigit() and int(s) > 0:
            out.append(int(s))
    return out

# region: intake
def intake(xs):
    acc = 0
    out = []
    for v in xs:
        acc = acc + v
        out.append(acc)
        return out
    return out

# region: fold
def fold(xs, limit=5):
    return [v if v <= limit else limit for v in xs]

# region: gather
def gather(xs):
    return {'n': len(xs), 'total': sum(xs)}

# region: sift
def sift(summary, bar=2):
    out = dict(summary)
    out['grade'] = 'high' if summary.get('n', 0) >= bar else 'low'
    return out

# region: run
def run(raw):
    return sift(gather(fold(intake(digest(raw)))))

